AUDITED_THEOREMS_BLOCK = re.compile(
    r'^AUDITED_THEOREMS = \(\n(?:    \"[^\"\\\n]+\",\n)+\)$',
    re.MULTILINE,
)
_COMPACT_AUDITED_THEOREMS_BLOCK = re.compile(
    r'^AUDITED_THEOREMS = tuple\(\n    """\n'
    r'(?P<body>(?:    [^\n]+\n)+)'
    r'    """\.split\(\)\n\)$',
    re.MULTILINE,
)


def parse_source(text: str) -> tuple[str, ...]:
    """Read either the compact inventory or the public source-literal shape."""
    compact = _COMPACT_AUDITED_THEOREMS_BLOCK.search(text)
    if compact is not None:
        return tuple(compact.group("body").split())
    literal = AUDITED_THEOREMS_BLOCK.search(text)
    if literal is not None:
        return ast.literal_eval(literal.group(0).split("=", 1)[1].strip())
    raise RefinementError("no AUDITED_THEOREMS block")


def render(theorems: tuple[str, ...]) -> str:
    if not theorems:
        raise RefinementError("the axiom audit reported no refinement theorems")
    unquotable = sorted(
        theorem
        for theorem in theorems
        if not theorem or set(theorem) & set('"\\\n')
    )
    if unquotable:
        raise RefinementError(
            "audited theorem name cannot be pinned as a source literal: "
            + ", ".join(unquotable)
        )
    body = "".join(f'    "{theorem}",\n' for theorem in theorems)
    return f"AUDITED_THEOREMS = (\n{body})"


def _render_compact(theorems: tuple[str, ...]) -> str:
    """Render the large checked-in inventory below the source line ceiling."""
    render(theorems)
    rows = [
        "    " + " ".join(theorems[index : index + 6])
        for index in range(0, len(theorems), 6)
    ]
    return (
        'AUDITED_THEOREMS = tuple(\n    """\n'
        + "\n".join(rows)
        + '\n    """.split()\n)'
    )


def rewrite(source: Path, theorems: tuple[str, ...]) -> None:
    """Repin either the compact inventory or the legacy public literal shape."""
    text = source.read_text(encoding="utf-8")
    if _COMPACT_AUDITED_THEOREMS_BLOCK.search(text) is not None:
        pattern = _COMPACT_AUDITED_THEOREMS_BLOCK
        replacement = _render_compact(theorems)
    else:
        pattern = AUDITED_THEOREMS_BLOCK
        replacement = render(theorems)
    updated, count = pattern.subn(
        lambda _: replacement,
        text,
        count=1,
    )
    if count != 1:
        raise RefinementError(
            f"{source}: the AUDITED_THEOREMS pin is not in its expected shape"
        )
    codec.atomic_write(source, updated.encode("utf-8"))
